// Metaballs: blobs that melt into each other. Each blob adds a value that grows
// near its centre, and the shape is wherever the total passes a threshold.
// iFloat0 on the [Timeline] is that threshold: lower, and the blobs merge.
#define threshold iFloat0

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // Coordinates with (0, 0) in the middle, and y from -1 to 1.
  vec2 uv = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

  // Add up every blob's contribution at this pixel.
  float field = 0.0;
  for (int i = 0; i < 6; i++) {
    float k = float(i);
    vec2 centre = 0.6 * vec2(sin(iTime * (0.5 + 0.13 * k) + 1.7 * k),
                             cos(iTime * (0.4 + 0.11 * k) + 2.3 * k));
    field += 0.05 / dot(uv - centre, uv - centre);
  }
  // Capped, as it grows without limit at each centre.
  field = min(field, 4.0 * threshold);

  // A soft edge about a pixel wide: fwidth is how fast the field changes per pixel.
  float inside = clamp(0.5 + (field - threshold) / max(fwidth(field), 1e-5), 0.0, 1.0);

  vec3 background = vec3(0.05, 0.06, 0.1) + vec3(0.12, 0.06, 0.2) * min(field / threshold, 1.0);
  vec3 blob = mix(vec3(0.95, 0.35, 0.55), vec3(1.0, 0.82, 0.45),
                  clamp((field - threshold) / (3.0 * threshold), 0.0, 1.0));
  fragColor = vec4(mix(background, blob, inside), 1.0);
}
